//! The `core` dispatcher — hosted plan §3.2 and §10 P2
//! (`docs/tabtivity_hosted_plan.md`).
//!
//! A server host (the Mobile sidecar in P2, the per-user daemon in P3) receives
//! `{cmd, args}` frames from a browser and answers them by calling the same
//! command bodies the desktop registers with Tauri — as plain functions, with a
//! [`CoreCtx`] whose caller is that client. The per-command wrappers are
//! **generated by `build.rs`** from the signatures in `src/commands/*.rs`
//! (`core_dispatch.rs` in `OUT_DIR`, included below): every `#[tauri::command]`
//! whose parameters are a [`crate::tauri_host::Ctx`] and JSON values gets one;
//! a command still taking `State`, `AppHandle`, `Window` or a raw IPC body is in
//! [`NOT_DISPATCHABLE`] with the reason, and `server_capabilities` hides it.
//!
//! Order of checks, by design (P0 handoff): the **class** first — an unknown
//! name, a `client`, `admin` (for a user) or `off` command is refused before any
//! argument is looked at — then whether a wrapper exists, then the arguments,
//! read by the camelCase keys Tauri uses and reported with Tauri's own wording
//! (``invalid args `key` for command `cmd`: …``). The server-side model
//! allowlist (`services::model_allowlist`) runs between the class check and the
//! call for the commands that reach the shared Ollama.
//!
//! Nothing here knows a WebSocket or a window: the transport hands in a
//! `CoreCtx` built for the caller and gets JSON back.

use std::future::Future;
use std::pin::Pin;

use app_core::CoreCtx;
use serde::de::DeserializeOwned;
use serde::Serialize;
use serde_json::Value;

use crate::services::command_class::{self, CommandClass};

/// What a wrapper answers: the command's `Ok` as JSON, or its error as JSON (a
/// string for the usual `Result<T, String>`, Tauri's `InvokeError` shape).
pub type BoxFuture = Pin<Box<dyn Future<Output = Result<Value, Value>> + Send>>;
/// One generated wrapper.
pub type Handler = fn(CoreCtx, Value) -> BoxFuture;

/// The generated wrappers. Machine-written, so the style lints a hand would
/// satisfy (a closure around a bare call) are allowed here and nowhere else.
#[allow(clippy::redundant_closure, clippy::let_unit_value, clippy::unit_arg, clippy::vec_init_then_push)]
mod generated {
    use super::*;
    include!(concat!(env!("OUT_DIR"), "/core_dispatch.rs"));
}
pub use generated::{dispatchable_names, handler, NOT_DISPATCHABLE};

/// Read one argument the way `#[tauri::command]` does: by key, a missing key
/// deserializing as `null` (so an `Option` is `None` and anything else fails),
/// with Tauri's own error wording.
fn arg<T: DeserializeOwned>(args: &Value, key: &str, cmd: &str) -> Result<T, Value> {
    T::deserialize(args.get(key).unwrap_or(&Value::Null))
        .map_err(|e| Value::String(format!("invalid args `{key}` for command `{cmd}`: {e}")))
}

fn to_json<T: Serialize>(value: T) -> Result<Value, Value> {
    serde_json::to_value(value).map_err(|e| Value::String(format!("serialize answer: {e}")))
}

fn result_to_json<T: Serialize, E: Serialize>(out: Result<T, E>) -> Result<Value, Value> {
    match out {
        Ok(v) => to_json(v),
        Err(e) => Err(serde_json::to_value(e).unwrap_or_else(|e| Value::String(format!("serialize error: {e}")))),
    }
}

/// Run a sync command body on the blocking pool (Tauri keeps sync commands off
/// its async runtime too). A panic in the body is an error answer, not a dead
/// connection.
async fn blocking<T: Send + 'static>(body: impl FnOnce() -> T + Send + 'static) -> Result<T, Value> {
    app_core::rt::spawn_blocking(body)
        .await
        .map_err(|e| Value::String(format!("command failed: {e}")))
}

/// Who the caller is to the server as a whole (plan §3.3 `admin`). The
/// single-user sidecar's token login is the box's admin; on a multi-user
/// server the gateway names the account's role in the connection's handshake
/// (`services::server`), and the daemon passes it in here per call.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Role {
    User,
    Admin,
}

impl Role {
    /// The wire token (`server_capabilities.role`, the gateway's handshake).
    pub fn as_str(self) -> &'static str {
        match self {
            Role::User => "user",
            Role::Admin => "admin",
        }
    }

    /// `as_str` undone; anything else is a user — the role fails closed.
    pub fn parse(token: &str) -> Role {
        if token == "admin" {
            Role::Admin
        } else {
            Role::User
        }
    }
}

/// Why a command is not served, as the frontend sees it (`server_capabilities`
/// rows and the error of a refused call). Wire shape `{code, reason?}`.
#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
#[serde(tag = "code", rename_all = "kebab-case")]
pub enum Refusal {
    /// No registered command of that name.
    Unknown,
    /// Runs on the machine the user sits at; the browser adapts or hides it.
    Client,
    /// Admin role only.
    Admin,
    /// Nothing in server mode can do it (`command_class::OffReason` token).
    Off { reason: &'static str },
    /// Classed `core` but its body still needs Tauri (`NOT_DISPATCHABLE`).
    Unsupported { reason: &'static str },
    /// A server feature (mail, calendar, todo) the admin or the user switched
    /// off (hosted plan §6.7); its data stays.
    FeatureOff { feature: &'static str },
}

/// The class check alone: unknown, `client`, `off`, or `admin` for a user.
/// What a transport answering a command itself (`read_file_bytes` as a
/// binary frame) must run before touching the frame — the wrapper table does
/// not apply to it, the class table always does.
pub fn class_refusal(cmd: &str, role: Role) -> Option<Refusal> {
    match command_class::class_of(cmd) {
        None => Some(Refusal::Unknown),
        Some(CommandClass::Client) => Some(Refusal::Client),
        Some(CommandClass::Off(reason)) => Some(Refusal::Off { reason: reason.as_str() }),
        Some(CommandClass::Admin) if role != Role::Admin => Some(Refusal::Admin),
        Some(CommandClass::Admin) | Some(CommandClass::Core) => None,
    }
}

/// Whether `cmd` is served for `role`, or why not. The class decides first;
/// the generated table second; arguments never (they are the call's business).
pub fn refusal(cmd: &str, role: Role) -> Option<Refusal> {
    if let Some(refused) = class_refusal(cmd, role) {
        return Some(refused);
    }
    if let Some(feature) = crate::services::server::feature_refusal(cmd) {
        return Some(Refusal::FeatureOff { feature: feature.as_str() });
    }
    if handler(cmd).is_some() {
        return None;
    }
    let reason = NOT_DISPATCHABLE
        .iter()
        .find(|(name, _)| *name == cmd)
        .map(|(_, reason)| *reason)
        .unwrap_or("no wrapper was generated for it");
    Some(Refusal::Unsupported { reason })
}

/// Is `cmd` served for `role`?
pub fn served(cmd: &str, role: Role) -> bool {
    refusal(cmd, role).is_none()
}

/// Call `cmd` with `args` (the JSON object the frontend's `invoke` sent) for
/// the client `ctx.caller` names. A refusal is an `Err` carrying the
/// [`Refusal`]'s JSON, so the frontend can tell "not served here" from a
/// command's own error.
pub async fn dispatch(ctx: &CoreCtx, role: Role, cmd: &str, mut args: Value) -> Result<Value, Value> {
    if let Some(refusal) = refusal(cmd, role) {
        return Err(serde_json::to_value(refusal).unwrap_or(Value::Null));
    }
    crate::services::model_allowlist::check(cmd, &args)?;
    confine_for_user(role, cmd, &mut args)?;
    let run = handler(cmd).expect("refusal() checked the wrapper exists");
    run(ctx.clone(), args).await
}

/// The `core` commands that take a path with no confinement of their own,
/// because on the desktop they stand in for an OS file dialog (`list_dir_all`
/// is the server-side picker's directory listing). An admin keeps that parity
/// — the box is theirs — a user is held to the roots every file command is
/// bound by (`fs::confine_user_path`): an empty start path becomes the
/// user's projects root instead of their home.
const USER_CONFINED_PATH: &[(&str, &str)] = &[("list_dir_all", "path")];

/// Confine the path argument of a [`USER_CONFINED_PATH`] command for a user.
/// Nothing for an admin, nothing for any other command.
fn confine_for_user(role: Role, cmd: &str, args: &mut Value) -> Result<(), Value> {
    if role == Role::Admin {
        return Ok(());
    }
    let Some((_, key)) = USER_CONFINED_PATH.iter().find(|(name, _)| *name == cmd) else {
        return Ok(());
    };
    let path = args.get(*key).and_then(Value::as_str).unwrap_or("").trim().to_string();
    let path = user_path(&path).map_err(Value::String)?;
    if let Some(map) = args.as_object_mut() {
        map.insert((*key).to_string(), Value::String(path));
    } else {
        *args = serde_json::json!({ *key: path });
    }
    Ok(())
}

/// A path a user may list or hand out: empty → the projects root; anything
/// else must lie under one of the user's allowed roots.
pub fn user_path(path: &str) -> Result<String, String> {
    let path = path.trim();
    if path.is_empty() {
        return Ok(crate::storage::root_work_dir().to_string_lossy().into_owned());
    }
    crate::commands::fs::confine_user_path(std::path::Path::new(path))?;
    Ok(path.to_string())
}

/// One `server_capabilities` row.
#[derive(Clone, Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct CommandCapability {
    pub name: &'static str,
    /// `core` / `client` / `admin` / `off`.
    pub class: &'static str,
    /// Whether a call from this client would be dispatched.
    pub served: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub refusal: Option<Refusal>,
}

/// What the frontend asks once after connecting (plan §3.3): every command's
/// class and whether this server serves it, plus the host's OS, which decides
/// spawn policy, path joins and install commands (`HOST_OS`, never the
/// browser's own).
#[derive(Clone, Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ServerCapabilities {
    /// The frame protocol the transport speaks (`web_client::PROTOCOL`).
    pub protocol: u32,
    /// `linux` / `windows` / `macos` — the server's.
    pub host_os: &'static str,
    /// `user` / `admin`.
    pub role: &'static str,
    pub commands: Vec<CommandCapability>,
}

/// The OS this host runs on, in the frontend's `PLATFORM` vocabulary.
pub fn host_os() -> &'static str {
    match std::env::consts::OS {
        "windows" => "windows",
        "macos" => "macos",
        _ => "linux",
    }
}

pub fn capabilities(role: Role, protocol: u32) -> ServerCapabilities {
    let commands = command_class::all()
        .iter()
        .map(|(name, class)| {
            let refusal = refusal(name, role);
            CommandCapability {
                name,
                class: class.as_str(),
                served: refusal.is_none(),
                refusal,
            }
        })
        .collect();
    ServerCapabilities {
        protocol,
        host_os: host_os(),
        role: role.as_str(),
        commands,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use app_core::{Caller, ClientId, CoreState, NullEvents};
    use std::sync::Arc;

    /// Commands classed `core` whose bodies still reach Tauri, so no wrapper
    /// exists yet. Each is a known P2/P3 gap (hosted handoff § P1 "Remaining"):
    /// the raw-body pair of `fs.rs` travels as binary frames through
    /// `web_client` instead, the five mail dialogs have path-taking siblings,
    /// and `apps.rs`/`browser.rs` keep their core halves for P3's split.
    const KNOWN_GAPS: &[&str] = &[
        "read_file_bytes",
        "write_file_bytes",
        // `commands/pdf_clip.rs`: `State<PdfClipboard>`, a singleton the core
        // state does not manage yet.
        "pdf_clip_get",
        "pdf_clip_set",
        // `commands/apps.rs`: the core half of a mixed file (P3 splits it).
        "run_script_detached",
        "mail_attach_pick",
        "mail_pgp_import_pick",
        "mail_contacts_import",
        "mail_contacts_export",
        "mail_attachment_save",
    ];

    fn ctx() -> CoreCtx {
        CoreCtx::new(Arc::new(CoreState::new()), Arc::new(NullEvents), Caller::Client(ClientId::new("web-1")))
    }

    #[test]
    fn every_core_command_has_a_wrapper_or_is_a_known_gap() {
        let mut unexpected = Vec::new();
        let mut healed = Vec::new();
        for name in command_class::names_in(CommandClass::Core) {
            let has = handler(name).is_some();
            if !has && !KNOWN_GAPS.contains(&name) {
                let reason = NOT_DISPATCHABLE.iter().find(|(n, _)| *n == name).map(|(_, r)| *r);
                unexpected.push(format!("{name} ({})", reason.unwrap_or("not a command file fn")));
            }
            if has && KNOWN_GAPS.contains(&name) {
                healed.push(name);
            }
        }
        assert!(unexpected.is_empty(), "core commands with no dispatcher wrapper:\n{}", unexpected.join("\n"));
        assert!(healed.is_empty(), "no longer gaps, drop them from KNOWN_GAPS: {healed:?}");
    }

    #[test]
    fn every_wrapper_names_a_registered_command() {
        let orphans: Vec<_> = dispatchable_names()
            .into_iter()
            .filter(|name| command_class::class_of(name).is_none())
            .collect();
        assert!(orphans.is_empty(), "wrappers for unregistered commands: {orphans:?}");
        assert!(dispatchable_names().len() > 500, "the generator read too little");
    }

    #[test]
    fn a_user_is_confined_where_an_admin_is_not() {
        assert_eq!(Role::parse("admin"), Role::Admin);
        assert_eq!(Role::parse("user"), Role::User);
        assert_eq!(Role::parse("root"), Role::User, "an unknown role fails closed");
        assert_eq!(Role::Admin.as_str(), "admin");
        // The class check alone serves `read_file_bytes` (core, no wrapper) and
        // refuses a client command and an admin command for a user.
        assert_eq!(class_refusal("read_file_bytes", Role::User), None);
        assert_eq!(class_refusal("clipboard_has_image", Role::User), Some(Refusal::Client));
        assert_eq!(class_refusal("install_ollama", Role::User), Some(Refusal::Admin));
        assert_eq!(class_refusal("desktop_logout", Role::User), Some(Refusal::Unknown), "transport-only names are the transport's");
        // An admin's `list_dir_all` is untouched; a user's empty path becomes
        // the projects root and an outside path is refused.
        let mut args = serde_json::json!({ "path": "" });
        confine_for_user(Role::Admin, "list_dir_all", &mut args).unwrap();
        assert_eq!(args["path"], "");
        confine_for_user(Role::User, "list_dir_all", &mut args).unwrap();
        assert_eq!(args["path"], crate::storage::root_work_dir().to_string_lossy().as_ref());
        let outside = tempfile::tempdir().unwrap();
        let mut args = serde_json::json!({ "path": outside.path().to_string_lossy() });
        let err = confine_for_user(Role::User, "list_dir_all", &mut args).unwrap_err();
        assert!(err.as_str().unwrap().contains("not in the current project"), "{err}");
        let mut other = serde_json::json!({ "path": outside.path().to_string_lossy() });
        confine_for_user(Role::User, "read_dir", &mut other).unwrap();
    }

    #[test]
    fn the_class_is_checked_before_anything_else() {
        assert_eq!(refusal("no_such_command", Role::Admin), Some(Refusal::Unknown));
        assert_eq!(refusal("clipboard_has_image", Role::Admin), Some(Refusal::Client));
        assert_eq!(refusal("save_settings", Role::Admin), Some(Refusal::Off { reason: "whole-document-save" }));
        assert_eq!(refusal("install_ollama", Role::User), Some(Refusal::Admin));
        assert_eq!(refusal("install_ollama", Role::Admin), None);
        assert_eq!(refusal("pty_write", Role::User), None);
        assert!(matches!(refusal("read_file_bytes", Role::User), Some(Refusal::Unsupported { .. })));
    }

    #[tokio::test]
    async fn a_refused_call_never_reaches_a_body() {
        let err = dispatch(&ctx(), Role::User, "clipboard_has_image", serde_json::json!({})).await.unwrap_err();
        assert_eq!(err["code"], "client");
        let err = dispatch(&ctx(), Role::User, "nope", Value::Null).await.unwrap_err();
        assert_eq!(err["code"], "unknown");
        let err = dispatch(&ctx(), Role::User, "save_boxes", Value::Null).await.unwrap_err();
        assert_eq!(err, serde_json::json!({ "code": "off", "reason": "whole-document-save" }));
    }

    #[tokio::test]
    async fn arguments_are_read_by_camel_case_key_and_reported_like_tauri() {
        // `agent_is_installed(id: String)` reads nothing but `PATH`.
        let err = dispatch(&ctx(), Role::User, "agent_is_installed", serde_json::json!({})).await.unwrap_err();
        assert_eq!(err, Value::String("invalid args `id` for command `agent_is_installed`: invalid type: null, expected a string".into()));
        let ok = dispatch(&ctx(), Role::User, "agent_is_installed", serde_json::json!({ "id": "no-such-cli-xyz" })).await.unwrap();
        assert_eq!(ok, Value::Bool(false));
    }

    #[tokio::test]
    async fn a_plain_return_and_a_unit_return_answer_json() {
        // `ollama_is_installed() -> bool` (a `PATH` probe).
        let out = dispatch(&ctx(), Role::User, "ollama_is_installed", Value::Null).await.unwrap();
        assert!(out.is_boolean());
    }

    #[test]
    fn capabilities_cover_every_row_and_carry_the_host() {
        let caps = capabilities(Role::User, 1);
        assert_eq!(caps.commands.len(), command_class::all().len());
        assert_eq!(caps.host_os, host_os());
        let served = caps.commands.iter().filter(|c| c.served).count();
        assert!(served > 450, "{served} served");
        let off = caps.commands.iter().find(|c| c.name == "keyring_unlock").unwrap();
        assert_eq!(off.class, "off");
        assert_eq!(off.refusal, Some(Refusal::Off { reason: "os-keychain" }));
        let admin = caps.commands.iter().find(|c| c.name == "pull_ollama_model").unwrap();
        assert!(!admin.served);
        assert!(capabilities(Role::Admin, 1).commands.iter().find(|c| c.name == "pull_ollama_model").unwrap().served);
        let json = serde_json::to_value(&caps).unwrap();
        assert!(json["commands"][0]["refusal"].is_null() || json["commands"][0]["refusal"]["code"].is_string());
    }

    #[test]
    fn camel_keys_match_tauri() {
        // The generator's rule is exercised through a generated wrapper: a
        // snake_case parameter is read under its camelCase key only.
        let rt = tokio::runtime::Runtime::new().unwrap();
        let err = rt
            .block_on(dispatch(&ctx(), Role::User, "agent_prompt_blame", serde_json::json!({ "project_id": "x" })))
            .unwrap_err();
        assert!(err.as_str().unwrap().starts_with("invalid args `projectId` for command `agent_prompt_blame`"), "{err}");
    }
}
